import React from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";


const BASE_URL = process.env.REACT_APP_BASE_URL;
function Logout() {
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await axios.post(
        BASE_URL + "/WebApplication/auth/logout",
        { withCredentials: true }
      );
      console.log("Logout Successful:");
      // Redirect to dashboard
      window.location.replace("/WebApplication/loginpage");
    } catch (err) {
      alert("message : Logout failed! Try again."); // 🔔 Show error globally
    }
  };


  return (
    <div className="d-flex justify-content-center align-items-center vh-100 bg-light">
      <div className="card shadow-lg border-0 rounded-4" style={{ width: "400px" }}>
        <div className="card-body text-center p-5">
          <h3 className="mb-3 text-danger">Are you sure?</h3>
          <p className="text-muted mb-4">
            You will be logged out from your account.
          </p>

          <div className="d-flex justify-content-center gap-3">
            <button
              className="btn btn-danger px-4 rounded-pill"
              onClick={handleLogout}
            >
              Yes, Logout
            </button>
            <button
              className="btn btn-secondary px-4 rounded-pill"
              onClick={() => navigate(-1)}
            >
              No, Go Back
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Logout;
