import React, { useState, useEffect } from "react";
import InputField from "../components/InputFields";
import myLogo from "../images/default2.png";
import { Link } from "react-router-dom";
import axios from "axios";
import { ArrowLeft } from "react-bootstrap-icons";
import { useLocation } from "react-router-dom";
import { useOutletContext } from "react-router-dom";
import LoadingSpinner from "../components/LoadingSpinner";
import { ClipboardList } from "lucide-react";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const NewEmployeeForm = () => {
    const [loading, setLoading] = useState(true);
    const [role, setRole] = useState("");
    const [department, setDepartment] = useState("");
    const [designation, setDesignation] = useState("");
    const [employeeId, setEmployeeId] = useState("");
    const [title, setTitle] = useState("")
    const [name, setName] = useState("")
    const [email, setEmail] = useState("")
    const [contact, setContact] = useState("")
    const [dateOfJoining, setDateOfJoining] = useState("")
    const [dateOfLeaving, setDateOfLeaving] = useState("")
    const [userStatus, setUserStatus] = useState("")
    const [roleTypes, setRoleTypes] = useState([]);
    const [departmentTypes, setDepartmentTypes] = useState([]);
    const designationTypes = ["Inventory Manager", "Project Manager", "Senior Software Engineer", "System Engineer", "Software Engineer", "Graduate Engineer Trainee"];
    const titleTypes = ["Mr.", "Mrs", "Miss", "Ms."];
    const userTypes = ["Enable", "Disable"];
    const [error, setError] = useState("");
    const { setAlert } = useOutletContext();
    const location = useLocation();
    const { dataObject } = location.state || {};
    const [selectedImage, setSelectedImage] = useState(null); // real File
    const [previewUrl, setPreviewUrl] = useState(null);
    const [image, setImage] = useState(null);     // preview

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedImage(file); // 👈 real File object
            setPreviewUrl(URL.createObjectURL(file)); // 👈 preview blob URL
        } else {
            alert("Please Select a JPG and PNG image.");
        }
    };

    useEffect(() => {
        loadRoleData();
        loadDepartmentData();
        if (dataObject) {
            setRole(dataObject.role.roleName || "");
            setEmployeeId(dataObject.employeeId || "");
            setDesignation(dataObject.designation || "");
            setTitle(dataObject.title || "");
            setName(dataObject.firstName || "");
            setEmail(dataObject.email || "");
            setContact(dataObject.contact || "");
            setDateOfLeaving(dataObject.dateOfLeaving || "");
            setDateOfJoining(dataObject.dateOfJoining || "");
            setUserStatus(dataObject.userStatus || "");
            setPreviewUrl(dataObject.image || "");
            setImage(dataObject.image || "")
        }
        setLoading(false);
    }, [dataObject]);

    const resetForm = async (e) => {
        setRole("");
        setEmployeeId("");
        setDesignation("");
        setTitle("");
        setName("");
        setEmail("");
        setContact("");
        setDateOfLeaving("");
        setDateOfJoining("");
        setUserStatus("");
        setPreviewUrl("");
        setImage("");
    }

    const loadRoleData = async () => {
        const response = await axios.get(
            BASE_URL + "/WebApplication/Controllers/getAllRoleInList",
            { withCredentials: true, } // 🚨 This ensures browser stores cookie 
        );
        setRoleTypes(response.data);
    };

    const loadDepartmentData = async () => {
        const response = await axios.get(
            BASE_URL + "/WebApplication/Controllers/getAllDepartmentInList",
            { withCredentials: true, } // 🚨 This ensures browser stores cookie 
        );
        setDepartmentTypes(response.data);
    };




    const handleUploadAndSubmit = async (e) => {
        e.preventDefault();
        try {

            if (!selectedImage) {
                // alert("Please select an image first!");
                await handleSubmitForm(e);
                return;
            } else {

                const imageData = new FormData();
                imageData.append("image", selectedImage);

                const response = await axios.post(
                    BASE_URL + "/WebApplication/Controllers/uploadImage",
                    imageData,
                    { headers: { "Content-Type": "multipart/form-data" } }
                );
                alert("Image uploaded successfully!");

                // ✅ Directly pass the uploaded image name/path
                await handleSubmitForm(e, response.data);
                return;
            }

        } catch (error) {
            console.error("Error uploading:", error);
        }
    };


    const isBlankOrSpaces = (value = "") =>
        value.trim().length === 0;

    const handleSubmitForm = async (e, uploadedImage) => {
        e.preventDefault();

        if (isBlankOrSpaces(employeeId) || isBlankOrSpaces(role)
            || isBlankOrSpaces(title) || isBlankOrSpaces(designation)
            || isBlankOrSpaces(employeeId) || isBlankOrSpaces(name)
            || isBlankOrSpaces(dateOfJoining)
            || isBlankOrSpaces(email) || isBlankOrSpaces(contact)) {
            alert("Please fill required column");
            return;
        }

        const data = {
            loginId: employeeId,
            role: { roleName: role },
            department: { departmentName: department },
            roleName: role,
            title: title,
            designation: designation,
            employeeId: employeeId,
            password: employeeId,
            firstName: name,
            lastName: name,
            dateOfJoining: dateOfJoining,
            dateOfLeaving: dateOfLeaving,
            email: email,
            contact: contact,
            dateTime: "",
            createdBy: "111"
        };

        try {
            const url = dataObject
                ? BASE_URL + "/WebApplication/Controllers/editLoginMaster"
                : BASE_URL + "/WebApplication/Controllers/insertLoginMaster";

            const response = await axios.post(url, data, { withCredentials: true });

            setAlert({ type: "success", message: "Success : " + response.data });
            resetForm();
        } catch (err) {
            setAlert({ type: "danger", message: "Error : " + err.response?.data });
            console.error(err);
        }
    };

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2 position-relative"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    {dataObject ? "Update Employee" : "New Employee"}</h4>
                <div
                    className="position-absolute top-50 start-0 translate-middle-y ms-3"
                    style={{ zIndex: 10 }}
                >
                    <Link
                        to="/WebApplication/masterDashboard/employeeMaster"
                        className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                    >
                        <ArrowLeft className="me-1" /><span className="d-none d-lg-inline">Back</span>
                    </Link>
                </div>
            </div>


            {error && <p className="text-danger text-center fw-semibold mt-2">{error}</p>}

            {loading ? (
                <LoadingSpinner message={`Loading .....`} />
            ) : (

                <div className="row g-1 p-1" style={{ maxHeight: "90vh", overflowY: "scroll" }}>

                    {/* Right Side - Illustration */}
                    <div className="col-md-4 bg-light rounded-3 shadow-sm">
                        <div className="d-flex justify-content-center align-items-center h-100">
                            <img
                                src={previewUrl || myLogo}  // 👈 replace with uploaded file if exists
                                alt="Project Illustration"
                                className="img-fluid"
                                style={{ maxWidth: "80%", opacity: 0.95 }}
                            />
                        </div>
                    </div>

                    {/* Left Side - Form */}
                    <div className="col-md-8" >
                        <form onSubmit={handleUploadAndSubmit} className="p-2 bg-light rounded-3 shadow-sm" style={{ height: "87vh", overflow: "auto" }}>
                            <div className="row g-1">
                                {/* Role */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Role"
                                        type="select"
                                        options={roleTypes}
                                        value={role}
                                        onChange={(e) => setRole(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Role */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Designation"
                                        type="select"
                                        options={designationTypes}
                                        value={designation}
                                        onChange={(e) => setDesignation(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                                                {/* Status */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Department"
                                        type="select"
                                        options={departmentTypes}
                                        value={department}
                                        onChange={(e) => setDepartment(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/*  Image */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="📌 Image"
                                        type="file"
                                        accept="image/png, image/jpeg"
                                        // value={customerAddress}
                                        onChange={handleImageChange}
                                    />
                                </div>

                                {/* Employee Id */}
                                <div className="col-md-3 px-2">
                                    <InputField
                                        label="Employee Id"
                                        type="text"
                                        placeholder="56"
                                        value={employeeId}
                                        onChange={(e) => setEmployeeId(e.target.value)}
                                        required={true}
                                        disabled={dataObject ? true : false}

                                    />
                                </div>

                                {/* Title */}
                                <div className="col-md-3 px-2">
                                    <InputField
                                        label="Title"
                                        type="select"
                                        options={titleTypes}
                                        value={title}
                                        onChange={(e) => setTitle(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Name*/}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Name"
                                        type="text"
                                        placeholder="Deepak"
                                        value={name}
                                        onChange={(e) => setName(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Email */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Email"
                                        type="text"
                                        placeholder="address@example.com"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Contact */}
                                <div className="col-md-12 px-2">
                                    <InputField
                                        label="Contact"
                                        type="text"
                                        placeholder="+91 7217699545"
                                        value={contact}
                                        onChange={(e) => setContact(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* D-o-j */}
                                <div className="col-md-3 px-2">
                                    <InputField
                                        label="D-O-J"
                                        type="date"
                                        value={dateOfJoining}
                                        onChange={(e) => setDateOfJoining(e.target.value)}
                                        required={true}
                                    />
                                </div>



                                {/* D-o-l */}
                                <div className="col-md-3 px-2">
                                    <InputField
                                        label="D-O-L"
                                        type="date"
                                        value={dateOfLeaving}
                                        onChange={(e) => setDateOfLeaving(e.target.value)}
                                    />
                                </div>



                                {/* Status */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Status"
                                        type="select"
                                        options={userTypes}
                                        value={userStatus}
                                        onChange={(e) => setUserStatus(e.target.value)}
                                        required={true}
                                    />
                                </div>


                                {/* Save Button */}
                                <div className="col-md-4 p-2">
                                    <button
                                        type="submit"
                                        size="lr"
                                        className="btn-woco btn btn-light btn-sm 
                                                    d-flex align-items-center 
                                                    fw-semibold shadow-sm"

                                        // className="btn btn-primary w-100 fw-bold mt-3 rounded-pill shadow-sm"
                                        style={{ fontSize: "1.1rem", letterSpacing: "0.5px" }}
                                    >
                                        {dataObject ? "💾 Update" : "💾 Save"}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );


};

export default NewEmployeeForm;
