// import logo from './logo.svg';
import './App.css';
import {
  BrowserRouter as Router,
  Route,
  Routes,
  //Link
} from "react-router-dom";
import { useEffect } from "react";
import Dashboard from './pages/Dashboard';
import Logout from "./pages/Logout";
import LogoPage from './pages/LogoPage';
import 'bootstrap/dist/css/bootstrap.min.css';
import { usePermissionStore } from "./auth/Permission";
import Unauthorized from "./components/Unauthorized"
import ModuleDashboard from './pages/ModuleDashboard';
import MasterRoutes from './routes/MasterRoutes';


function App() {

  const fetchPermissions = usePermissionStore(state => state.fetchPermissions);
  const permissions = usePermissionStore(state => state.permissions);

  useEffect(() => {
    if (permissions.length === 0) {
      fetchPermissions();
    }
  }, []);

  return (
    <>
      <Router future={{
        v7_startTransition: true,
        v7_relativeSplatPath: true
      }}>
        <Routes>
          <Route path="/WebApplication/unauthorizeaccess" element={<Unauthorized />} />
          <Route path="/WebApplication/masterDashboard" element={<Dashboard />}>
            {/* Default */}
            <Route index element={<LogoPage />} />
            {/* <Route path="quizDashboard" element={<QuizDashboard />} /> */}
            <Route path="unauthorizeaccess" element={<Unauthorized />} />
            <Route
              path="logout"
              element={
                <Logout />
              }
            />
            {MasterRoutes}
          </Route>
        </Routes>
      </Router>
    </>
  );
}

export default App;


