import React, { useState, useEffect } from "react";
import InputField from "../components/InputFields";
import myLogo from "../images/default2.png";
import { Link } from "react-router-dom";
import axios from "axios";
import { ArrowLeft } from "react-bootstrap-icons";
import { useLocation } from "react-router-dom";
import { useOutletContext } from "react-router-dom";
import LoadingSpinner from "../components/LoadingSpinner";
import { ClipboardList } from "lucide-react";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const NewCompoundForm = () => {
    const [loading, setLoading] = useState(true);
    const [compoundDataId, setCompoundDataId] = useState("");
    const [compound, setCompound] = useState("");
    const [batchWeight, setBatchWeight] = useState("");
    const [loadtime, setLoadtime] = useState("");
    const [mixTime, setMixTime] = useState("");
    const [blendTime, setBlendTime] = useState("");
    const [handleTime, setHandleTime] = useState("");
    const [reLoadTime, setReLoadTime] = useState("")
    const [reMixTime, setReMixTime] = useState("")
    const [reBlendTime, setReBlendTime] = useState("")
    const [reHandleTime, setReHandleTime] = useState("")
    const [error, setError] = useState("");
    const { setAlert } = useOutletContext();
    const location = useLocation();
    const { object } = location.state || {};
    const [selectedImage, setSelectedImage] = useState(null); // real File
    const [previewUrl, setPreviewUrl] = useState(null);
    const [image, setImage] = useState(null);       // preview

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedImage(file); // 👈 real File object
            setPreviewUrl(URL.createObjectURL(file)); // 👈 preview blob URL
        } else {
            alert("Please Select a JPG and PNG image.");
        }
    };

    useEffect(() => {
        
        if (object) {
            setCompoundDataId(object.compoundDataId || "");
            setCompound(object.compound || "");
            setBatchWeight(object.batchWeight || "");
            setLoadtime(object.loadtime || "");
            setMixTime(object.mixTime || "");
            setBlendTime(object.blendTime || "");
            setHandleTime(object.handleTime || "");
            setReLoadTime(object.reLoadTime || "");
            setReMixTime(object.reMixTime || "");
            setReBlendTime(object.reBlendTime || "");
            setReHandleTime(object.reHandleTime || "");
            setImage(object.image || "")
            setPreviewUrl(object.image || "");
        }

        setLoading(false);
    }, [object]);

    const resetForm = async (e) => {
        setCompoundDataId("");
        setCompound("");
        setBatchWeight("");
        setBatchWeight("");
        setLoadtime("");
        setMixTime("");
        setBlendTime("");
        setHandleTime("");
        setReLoadTime("");
        setReMixTime("");
        setReBlendTime("");
        setReHandleTime("");
        setPreviewUrl("");
        setImage("");
    }


    const handleUploadAndSubmit = async (e) => {
        e.preventDefault();
        try {

            if (!selectedImage) {
                // alert("Please select an image first!");
                await handleSubmitForm(e);
                return;
            } else {

                const imageData = new FormData();
                imageData.append("image", selectedImage);

                const response = await axios.post(
                    BASE_URL + "/WebApplication/Controllers/uploadImage",
                    imageData,
                    { headers: { "Content-Type": "multipart/form-data" } }
                );
                alert("Image uploaded successfully!");

                // ✅ Directly pass the uploaded image name/path
                await handleSubmitForm(e, response.data);
                return;
            }

        } catch (error) {
            console.error("Error uploading:", error);
        }
    };


    const isBlankOrSpaces = (value = "") =>
        value.trim().length === 0;

    const handleSubmitForm = async (e, uploadedImage) => {
        e.preventDefault();

        if (isBlankOrSpaces(compound) || isBlankOrSpaces(batchWeight)
            || isBlankOrSpaces(reLoadTime)) {
            alert("Please fill required column");
            return;
        }

        const data = {
            compoundDataId: parseInt(compoundDataId),
            reHandleTime,
            reBlendTime,
            reMixTime,
            reLoadTime,
            handleTime,
            blendTime,
            mixTime,
            loadtime,
            batchWeight,
            compound,
            image: uploadedImage ? "/WebApplication/trainingResouces/" + uploadedImage + ".png" : image,   // ✅ use uploaded image instead of state
            dateTime: "",
            createdBy: "111",
        };

        try {
            const url = object
                ? BASE_URL + "/WebApplication/Controllers/editCompoundDataMaster"
                : BASE_URL + "/WebApplication/Controllers/insertCompoundDataMaster";

            const response = await axios.post(url, data, { withCredentials: true });

            setAlert({ type: "success", message: "Success : " + response.data });
            resetForm();
        } catch (err) {
            setAlert({ type: "danger", message: "Error : " + err.response?.data });
            console.error(err);
        }
    };

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2 position-relative"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    {object ? "Update Compound" : "New Compound"}</h4>
                <div
                    className="position-absolute top-50 start-0 translate-middle-y ms-3"
                    style={{ zIndex: 10 }}
                >
                    <Link
                        to="/WebApplication/masterDashboard/compoundMaster"
                        className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                    >
                        <ArrowLeft className="me-1" /><span className="d-none d-lg-inline">Back</span>
                    </Link>
                </div>
            </div>


            {error && <p className="text-danger text-center fw-semibold mt-2">{error}</p>}

            {loading ? (
                <LoadingSpinner message={`Loading .....`} />
            ) : (

                <div className="row g-1 p-1" style={{ maxHeight: "90vh", overflowY: "scroll" }}>

                    {/* Right Side - Illustration */}
                    <div className="col-md-4 bg-light rounded-3 shadow-sm">
                        <div className="d-flex justify-content-center align-items-center h-100">
                            <img
                                src={previewUrl || myLogo}  // 👈 replace with uploaded file if exists
                                alt="Project Illustration"
                                className="img-fluid"
                                style={{ maxWidth: "80%", opacity: 0.95 }}
                            />
                        </div>
                    </div>

                    {/* Left Side - Form */}
                    <div className="col-md-8" >
                        <form onSubmit={handleUploadAndSubmit} className="p-2 bg-light rounded-3 shadow-sm" style={{ height: "87vh", overflow: "auto" }}>
                            <div className="row g-1">
                                {/* Plant Name. */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Compound Name"
                                        type="text"
                                        placeholder=""
                                        value={compound}
                                        onChange={(e) => setCompound(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Image */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Image"
                                        type="file"
                                        accept="image/png, image/jpeg"
                                        // value={customerAddress}
                                        onChange={handleImageChange}
                                    />
                                </div>


                                {/* Project Name */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Batch Weight"
                                        type="text"
                                        placeholder=""
                                        value={batchWeight}
                                        onChange={(e) => setBatchWeight(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Project Name */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Load Time"
                                        type="text"
                                        placeholder=""
                                        value={loadtime}
                                        onChange={(e) => setLoadtime(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Project Manager */}
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Mix Time"
                                        type="text"
                                        placeholder=""
                                        value={mixTime}
                                        onChange={(e) => setMixTime(e.target.value)}
                                        required={true}
                                    />
                                </div>
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Blend Time"
                                        type="text"
                                        placeholder=""
                                        value={blendTime}
                                        onChange={(e) => setBlendTime(e.target.value)}
                                        required={true}
                                    />
                                </div>
                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Handle Time"
                                        type="text"
                                        placeholder=""
                                        value={handleTime}
                                        onChange={(e) => setHandleTime(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Reload Time"
                                        type="text"
                                        placeholder=""
                                        value={reLoadTime}
                                        onChange={(e) => setReLoadTime(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Remix Time"
                                        type="text"
                                        placeholder=""
                                        value={reMixTime}
                                        onChange={(e) => setReMixTime(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Reblend Time"
                                        type="text"
                                        placeholder=""
                                        value={reBlendTime}
                                        onChange={(e) => setReBlendTime(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                <div className="col-md-4 px-2">
                                    <InputField
                                        label="Rehandle Time"
                                        type="text"
                                        placeholder=""
                                        value={reHandleTime}
                                        onChange={(e) => setReHandleTime(e.target.value)}
                                        required={true}
                                    />
                                </div>

                                {/* Save Button */}
                                <div className="col-md-4 p-2">
                                    <button
                                        type="submit"
                                        size="lr"
                                        className="btn-woco btn btn-light btn-sm 
                                                    d-flex align-items-center 
                                                    fw-semibold shadow-sm"

                                        // className="btn btn-primary w-100 fw-bold mt-3 rounded-pill shadow-sm"
                                        style={{ fontSize: "1.1rem", letterSpacing: "0.5px" }}
                                    >
                                        {object ? "💾 Update" : "💾 Save"}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );


};

export default NewCompoundForm;
