import React, { useState, useEffect } from "react";
import InputField from "../components/InputFields";
import myLogo from "../images/default2.png";
import { Link } from "react-router-dom";
import axios from "axios";
import { ArrowLeft } from "react-bootstrap-icons";
import { useLocation } from "react-router-dom";
import { useOutletContext } from "react-router-dom";
import SearchInputFields from "../components/SearchInputFields"
import LoadingSpinner from "../components/LoadingSpinner";
import { ClipboardList } from "lucide-react";
const BASE_URL = process.env.REACT_APP_BASE_URL;

const NewStoreMaterialForm = () => {
    const [loading, setLoading] = useState(true);
    const [storeMaterialId, setStoreMaterialId] = useState("");
    const [material, setMaterial] = useState("");
    const [description, setDescription] = useState("");
    const [category, setCategory] = useState("");
    const [categoryTypes, setCategoryTypes] = useState([]);
    const [error, setError] = useState("");
    const { setAlert } = useOutletContext();
    const location = useLocation();
    const { object } = location.state || {};
    const [selectedImage, setSelectedImage] = useState(null); // real File
    const [previewUrl, setPreviewUrl] = useState(null);
    const [image, setImage] = useState(null);       // preview

    const handleImageChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setSelectedImage(file); // 👈 real File object
            setPreviewUrl(URL.createObjectURL(file)); // 👈 preview blob URL
        } else {
            alert("Please Select a JPG and PNG image.");
        }
    };

    useEffect(() => {
        // // Runs on mount
        loadStoreCategoryListData();
        // loadUserListData();
        // loadPersonListData();
        // loadGroupListData();

        // Runs when object changes
        if (object) {
            setStoreMaterialId(object.storeMaterialId || "");
            setMaterial(object.material || "");
            setDescription(object.description || "");
            setCategory(object?.category?.category || "")
            setImage(object.image || "")
            setPreviewUrl(object.image || "");
        }

        setLoading(false);
    }, [object]);

    const resetForm = async (e) => {
        setStoreMaterialId("");
        setMaterial("");
        setDescription("");
        setCategory("");
        setPreviewUrl("");
        setImage("");
    }

    // Handle form change
    const loadStoreCategoryListData = async () => {
        const response = await axios.get(
            BASE_URL + "/WebApplication/Controllers/getAllStoreCategoryInList",
            { withCredentials: true, } // 🚨 This ensures browser stores cookie 
        );
        setCategoryTypes(response.data);
    };

    const handleUploadAndSubmit = async (e) => {
        e.preventDefault();
        try {

            if (!selectedImage) {
                // alert("Please select an image first!");
                await handleSubmitForm(e);
                return;
            } else {

                const imageData = new FormData();
                imageData.append("image", selectedImage);

                const response = await axios.post(
                    BASE_URL + "/WebApplication/Controllers/uploadImage",
                    imageData,
                    { headers: { "Content-Type": "multipart/form-data" } }
                );
                alert("Image uploaded successfully!");

                // ✅ Directly pass the uploaded image name/path
                await handleSubmitForm(e, response.data);
                return;
            }

        } catch (error) {
            console.error("Error uploading:", error);
        }
    };


    const isBlankOrSpaces = (value = "") =>
        value.trim().length === 0;

    const handleSubmitForm = async (e, uploadedImage) => {
        e.preventDefault();

        if (isBlankOrSpaces(material) || isBlankOrSpaces(description)
            || isBlankOrSpaces(category)) {
            alert("Please fill required column");
            return;
        }

        const data = {
            storeMaterialId: parseInt(storeMaterialId),
            material,
            description,
            category: {
                category
            },
            image: uploadedImage ? "/WebApplication/trainingResouces/" + uploadedImage + ".png" : image,   // ✅ use uploaded image instead of state
            dateTime: "",
            createdBy: "111",
        };

        try {
            const url = object
                ? BASE_URL + "/WebApplication/Controllers/editStoreMaterialMaster"
                : BASE_URL + "/WebApplication/Controllers/insertStoreMaterialMaster";

            const response = await axios.post(url, data, { withCredentials: true });

            setAlert({ type: "success", message: "Success : " + response.data });
            resetForm();
        } catch (err) {
            setAlert({ type: "danger", message: "Error : " + err.response?.data });
            console.error(err);
        }
    };

    return (
        <div className="card shadow-lg rounded-0 border-0 bg-light d-flex flex-column p-2"
            style={{
                width: "100%",
                minHeight: "100vh",
                background: "#f4f6f8",
            }}>
            {/* Header */}
            <div className="px-4 py-2 position-relative"
                style={{
                    background: "linear-gradient(90deg, #0f6b5b, #0b4f43)",
                    color: "white"
                }}>
                {/* Title */}
                <h4 className="text-end fw-bold mb-0"><ClipboardList size={30} viewBox="0 1 24 24" className="me-2 text-white" />
                    {object ? "Update Store Material Category" : "New Store Material Category"}</h4>
                <div
                    className="position-absolute top-50 start-0 translate-middle-y ms-3"
                    style={{ zIndex: 10 }}
                >
                    <Link
                        to="/WebApplication/masterDashboard/storeMaterialMaster"
                        className="btn btn-light btn-sm d-flex align-items-center fw-semibold shadow-sm"
                    >
                        <ArrowLeft className="me-1" /><span className="d-none d-lg-inline">Back</span>
                    </Link>
                </div>
            </div>


            {error && <p className="text-danger text-center fw-semibold mt-2">{error}</p>}

            {loading ? (
                <LoadingSpinner message={`Loading .....`} />
            ) : (

                <div className="row g-1 p-1" style={{ maxHeight: "90vh", overflowY: "scroll" }}>

                    {/* Right Side - Illustration */}
                    <div className="col-md-4 bg-light rounded-3 shadow-sm">
                        <div className="d-flex justify-content-center align-items-center h-100">
                            <img
                                src={previewUrl || myLogo}  // 👈 replace with uploaded file if exists
                                alt="Project Illustration"
                                className="img-fluid"
                                style={{ maxWidth: "80%", opacity: 0.95 }}
                            />
                        </div>
                    </div>

                    {/* Left Side - Form */}
                    <div className="col-md-8" >
                        <form onSubmit={handleUploadAndSubmit} className="p-2 bg-light rounded-3 shadow-sm" style={{ height: "87vh", overflow: "auto" }}>
                            <div className="row g-1">
                                {/* Plant Name. */}
                                <div className="col-md-6 px-2">
                                    <SearchInputFields
                                        label="Material"
                                        type="text"
                                        placeholder=""
                                        value={material}
                                        onChange={(e) => setMaterial(e.target.value)}
                                        required={true}
                                    />
                                </div>


                                {/* Image */}
                                <div className="col-md-6 px-2">
                                    <InputField
                                        label="Image"
                                        type="file"
                                        accept="image/png, image/jpeg"
                                        // value={customerAddress}
                                        onChange={handleImageChange}
                                    />
                                </div>

                                <div className="col-md-12 px-2">
                                    <SearchInputFields
                                        label="Category"
                                        type="select"
                                        placeholder=""
                                        value={category}
                                        options={categoryTypes}
                                        onChange={(e) => setCategory(e.target.value)}
                                        required={true}
                                    />
                                </div>


                                {/* Project Name */}
                                <div className="col-md-12 px-2">
                                    <SearchInputFields
                                        label="Description"
                                        type="text"
                                        placeholder=""
                                        value={description}
                                        onChange={(e) => setDescription(e.target.value)}
                                        required={true}
                                    />
                                </div>


                                {/* Save Button */}
                                <div className="col-md-4 p-2">
                                    <button
                                        type="submit"
                                        size="lr"
                                        className="btn-woco btn btn-light btn-sm 
                                                    d-flex align-items-center 
                                                    fw-semibold shadow-sm"

                                        // className="btn btn-primary w-100 fw-bold mt-3 rounded-pill shadow-sm"
                                        style={{ fontSize: "1.1rem", letterSpacing: "0.5px" }}
                                    >
                                        {object ? "💾 Update" : "💾 Save"}
                                    </button>
                                </div>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );


};

export default NewStoreMaterialForm;
